#include <iostream>
#include <stdexcept>
#include <string>

class Resource {
public:
    explicit Resource(const std::string& name) : name_(name) {
        std::cout << "Constructed: " << name_ << "\n";
    }
    ~Resource() {
        std::cout << "Destroyed: " << name_ << "\n";
    }
private:
    std::string name_;
};

class ComplexDevice {
public:
    ComplexDevice(bool failOnSecond) 
        : r1_("BufferA"), r2_("BufferB") {
        if (failOnSecond) {
            std::cout << "Fault detected during initialization!\n";
            throw std::runtime_error("Initialization failure in ComplexDevice");
        }
        std::cout << "ComplexDevice successfully initialized\n";
    }
    ~ComplexDevice() {
        std::cout << "Destroyed ComplexDevice\n";
    }
private:
    Resource r1_;
    Resource r2_;
};

int main() {
    try {
        std::cout << "--- Attempting to create device ---\n";
        ComplexDevice dev(true);
    } catch (const std::exception& ex) {
        // Polymorphically catches std::runtime_error via base reference
        std::cout << "Caught polymorphic exception: " << ex.what() << "\n";
    }
    return 0;
}

