#include <iostream>
#include <memory>
#include <stdexcept>

// Class Integer mirroring textbook Figs. 22.7 - 22.8
class Integer {
public:
    explicit Integer(int i = 0) : value(i) {
        std::cout << "Constructor for Integer " << value << "\n";
    }
    ~Integer() {
        std::cout << "Destructor for Integer " << value << "\n";
    }
    void setInteger(int i) { value = i; }
    int getInteger() const { return value; }
private:
    int value;
};

void testUniquePtr(bool triggerException) {
    std::cout << "Creating unique_ptr object\n";
    std::unique_ptr<Integer> ptrToInteger = std::make_unique<Integer>(7);

    // Manipulating through overloaded -> and *
    ptrToInteger->setInteger(99);
    std::cout << "Integer after setInteger: " << (*ptrToInteger).getInteger() << "\n";

    if (triggerException) {
        std::cout << "Exception thrown before function finishes!\n";
        throw std::runtime_error("Simulated failure");
    }
}

int main() {
    try {
        testUniquePtr(true);
    } catch (const std::exception& e) {
        std::cout << "Exception caught in main: " << e.what() << "\n";
    }
    std::cout << "Terminating program cleanly\n";
    return 0;
}
